// Explicit native traces also work in CLI versions that ignore net.connectsTo.
export function KiCadNet({ name, connectsTo }: {
    name: string;
    connectsTo: string[];
}) { return <><net name={name}/>{connectsTo.map(target => <trace key={target} from={target} to={'net.' + name}/>)}</>; }
